import { mkdir, readdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { createLogger } from "@aso/shared";

const log = createLogger("state");

/** Bump when the snapshot shape changes incompatibly; older files are then set aside, not loaded. */
const STATE_VERSION = 1;
const SAVE_DELAY_MS = 200;
/** Conversation ids are generated by workers; anything else never becomes a file name. */
const SAFE_ID = /^[A-Za-z0-9_-]{1,128}$/;

export interface Snapshot<T, P> {
  tasks: T[];
  plans: P[];
}

/**
 * Hub state on disk, so tasks, plans and agent conversations survive a Hub restart.
 * `state.json` holds tasks + plans; each agent conversation is its own file because it grows
 * with every turn. Writes go to a temp file and are renamed into place, so a crash leaves the
 * previous version intact.
 */
export class StateStore {
  private timer?: NodeJS.Timeout;
  private snapshot?: () => Snapshot<unknown, unknown>;
  /** Serialises writes so an older snapshot can never overwrite a newer one. */
  private writes: Promise<unknown> = Promise.resolve();
  private closed = false;

  constructor(readonly dir: string) {}

  private get stateFile() {
    return path.join(this.dir, "state.json");
  }

  private get conversationDir() {
    return path.join(this.dir, "conversations");
  }

  /** The saved tasks and plans, or undefined when there is nothing (usable) to restore. */
  async load<T, P>(): Promise<Snapshot<T, P> | undefined> {
    let text: string;
    try {
      text = await readFile(this.stateFile, "utf8");
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return undefined;
      throw err;
    }
    try {
      const data = JSON.parse(text) as { version?: unknown; tasks?: unknown; plans?: unknown };
      if (data.version !== STATE_VERSION) throw new Error(`unsupported version ${String(data.version)}`);
      if (!Array.isArray(data.tasks) || !Array.isArray(data.plans)) throw new Error("tasks and plans must be arrays");
      return { tasks: data.tasks as T[], plans: data.plans as P[] };
    } catch (err) {
      // Never delete what we can't read: keep it next to the fresh state for a human to inspect.
      const aside = `${this.stateFile}.unreadable-${Date.now()}`;
      await rename(this.stateFile, aside);
      log.error(`could not read ${this.stateFile} (${(err as Error).message}); moved it to ${aside} and starting empty`);
      return undefined;
    }
  }

  /** Save soon; changes arriving in the meantime are batched into one write. */
  scheduleSave(snapshot: () => Snapshot<unknown, unknown>): void {
    if (this.closed) return;
    this.snapshot = snapshot;
    this.timer ??= setTimeout(() => void this.flush(), SAVE_DELAY_MS);
  }

  /** Write any scheduled save now (called on shutdown). */
  flush(): Promise<unknown> {
    clearTimeout(this.timer);
    this.timer = undefined;
    const snapshot = this.snapshot;
    this.snapshot = undefined;
    if (snapshot) {
      const { tasks, plans } = snapshot();
      const text = JSON.stringify({ version: STATE_VERSION, savedAt: new Date().toISOString(), tasks, plans });
      this.enqueue(() => this.writeAtomic(this.stateFile, text));
    }
    return this.writes;
  }

  /** Write what is pending, then ignore further changes (the Hub is shutting down). */
  async close(): Promise<void> {
    await this.flush();
    this.closed = true;
  }

  saveConversation(id: string, data: unknown): void {
    if (this.closed) return;
    if (!SAFE_ID.test(id)) return log.warn(`not saving conversation with unsafe id ${JSON.stringify(id)}`);
    const text = JSON.stringify(data);
    this.enqueue(() => this.writeAtomic(path.join(this.conversationDir, `${id}.json`), text));
  }

  deleteConversation(id: string): void {
    if (this.closed || !SAFE_ID.test(id)) return;
    this.enqueue(() => rm(path.join(this.conversationDir, `${id}.json`), { force: true }));
  }

  /** Every saved conversation; unreadable files are skipped with a warning. */
  async loadConversations<C>(): Promise<C[]> {
    let files: string[];
    try {
      files = await readdir(this.conversationDir);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw err;
    }
    const out: C[] = [];
    for (const file of files.filter((f) => f.endsWith(".json"))) {
      try {
        out.push(JSON.parse(await readFile(path.join(this.conversationDir, file), "utf8")) as C);
      } catch (err) {
        log.warn(`skipping unreadable conversation ${file}: ${(err as Error).message}`);
      }
    }
    return out;
  }

  private enqueue(fn: () => Promise<unknown>): void {
    this.writes = this.writes.then(fn).catch((err: Error) => log.error(`saving Hub state failed: ${err.message}`));
  }

  private async writeAtomic(file: string, text: string): Promise<void> {
    await mkdir(path.dirname(file), { recursive: true });
    const tmp = `${file}.tmp-${process.pid}`;
    await writeFile(tmp, text);
    await rename(tmp, file);
  }
}
